package domain

import "time"

// Wallet is an account that holds a monetary balance in a single currency.
//
// Balance is stored as an integer number of minor units (for example cents)
// to avoid floating point rounding errors in financial calculations.
type Wallet struct {
	ID        string
	Balance   int64
	Currency  string
	CreatedAt time.Time
	UpdatedAt time.Time
}

// NewWallet builds a wallet with the given id and opening balance, validating
// the inputs. The id is generated by the caller (service layer) so the domain
// stays deterministic and easy to test. A zero or positive opening balance is
// allowed; the currency defaults to DefaultCurrency when empty.
func NewWallet(id string, openingBalance int64, currency string) (*Wallet, error) {
	if id == "" {
		return nil, newValidationError("id", "wallet id is required")
	}
	if openingBalance < 0 {
		return nil, newValidationError("balance", "opening balance cannot be negative")
	}
	if currency == "" {
		currency = DefaultCurrency
	}
	now := time.Now().UTC()
	return &Wallet{
		ID:        id,
		Balance:   openingBalance,
		Currency:  currency,
		CreatedAt: now,
		UpdatedAt: now,
	}, nil
}

// DefaultCurrency is used when a wallet is created without an explicit currency.
const DefaultCurrency = "USD"

// HasSufficientBalance reports whether the wallet can fund a debit of amount.
func (w *Wallet) HasSufficientBalance(amount int64) bool {
	return w.Balance >= amount
}

// Debit decreases the wallet balance by amount. It returns ErrInsufficientFunds
// if the balance would go negative, protecting the invariant that a balance can
// never be below zero.
func (w *Wallet) Debit(amount int64) error {
	if amount <= 0 {
		return newValidationError("amount", "debit amount must be positive")
	}
	if !w.HasSufficientBalance(amount) {
		return ErrInsufficientFunds
	}
	w.Balance -= amount
	return nil
}

// Credit increases the wallet balance by amount.
func (w *Wallet) Credit(amount int64) error {
	if amount <= 0 {
		return newValidationError("amount", "credit amount must be positive")
	}
	w.Balance += amount
	return nil
}
